import React, {useEffect, useState} from 'react';
import axios from "axios";
import {useParams, Route, Link} from "react-router-dom";
import ImageGallery from "react-image-gallery";
import "react-image-gallery/styles/css/image-gallery.css";


function ProductsPage() {

    const {categoryId} = useParams();
    const [products, setProducts] = useState([]);
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(true);





    useEffect(() => {
        const fetchData = async () => {
            try {
                const url = categoryId
                    ? `http://localhost:3000/product?categoryId= ${categoryId}`
                    : 'http://localhost:8080/product';
                const response = await axios.get(url);
                setProducts(response.data);
            } catch (err) {
                setError(err)
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, [categoryId]);


    if (loading) {
        return <div>Loading...</div>;
    }
    if (error) {
        return <div>Error: {error.message}</div>
    }

 return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
    <h1>{categoryId ? `Products in Category ${categoryId}` : 'All Products'}</h1>
{products.length > 0 ? (
        <ul>
            {products.map(product => (
                <li key={product.id} style={{display:'flex', alignItems: 'center', }}>
                    {product.name}
                    {product.images && product.images.length > 0 ? (
                        <div style = {{marginRight: '10px'}}>
                                <img key = {product.images[0].id} src={product.images[0].path} alt = {product.name} width ="50px" height = "50px" />
                        </div>
                    ): null}
                </li>
            ))}
        </ul>
    ) : (
        <p>No products found for this category.</p>
    )}
</div>
);
}

export default ProductsPage;
